#!/usr/bin/env bash
# Cowfee Raid Tools test suite: Lua harnesses run with fengari under Node (no Lua runtime needed).
#   bash CRT_Dev/Tests/run_all.sh [addon folder]   defaults to the checkout this script is in
# First run: cd CRT_Dev/Tests && npm install. Prints each group; ends with a summary line and exits 1 on any failure.
W="${1:-$(cd "$(dirname "$0")/../.." && (pwd -W 2>/dev/null || pwd))}"
cd "$(dirname "$0")"
for t in "store CRT_Modules/Timeline/Data.lua" "record CRT_Modules/Timeline/Data.lua" "journal CRT_Modules/Timeline/Journal.lua" "reference CRT_Modules/Timeline/Database.lua CRT_Modules/Timeline/Reference.lua" "probe CRT_Dev/Dev/TimelineProbe.lua" "lanes CRT_Modules/Timeline/Data.lua CRT_Modules/Timeline/Database.lua CRT_Modules/Timeline/Reference.lua CRT_Modules/Timeline/Lanes.lua" "view CRT_Modules/Timeline/Data.lua CRT_Modules/Timeline/Database.lua CRT_Modules/Timeline/Reference.lua CRT_Modules/Timeline/Lanes.lua CRT_Modules/Timeline/View.lua" "page CRT_Modules/Timeline/Data.lua CRT_Modules/Timeline/Database.lua CRT_Modules/Timeline/Reference.lua CRT_Modules/Timeline/Lanes.lua CRT_Modules/Timeline/ReferencePage.lua CRT_Modules/Timeline/SettingsTab.lua CRT_Modules/Timeline/Page.lua CRT_Modules/Timeline/Journal.lua"; do
  set -- $t; n=$1; shift; case $n in reference|view|page) set -- "$@" CRT_Data/Bosses/Registry.lua CRT_Data/Seasons/Midnight-S1/Season.lua CRT_Data/Seasons/Midnight-S1/NekzaliTheSoulcoiler.lua;; esac; [ "$n" = page ] && set -- "$@" CRT_Modules/Timeline/ReviewTab.lua CRT_Modules/Timeline/Rehearsal.lua CRT_Modules/Timeline/RehearsalWindow.lua CRT_Core/Slash.lua; args=""; for f in "$@"; do args="$args \"$W/$f\""; done
  echo "== $n"; eval node run_timeline_$n.js $args 2>&1 | tail -${TAIL:-40}; echo "exit ${PIPESTATUS[0]}"
done
echo "== profiles"; node run_profiles.js "$W/CRT_Core/Profiles.lua" 2>&1 | tail -30; echo "exit ${PIPESTATUS[0]}"
echo "== settings"; node run_settings.js "$W" 2>&1 | tail -15; echo "exit ${PIPESTATUS[0]}"
WA="$W"
echo "== alerts rules"; node run_alerts_rules.js "$WA/CRT_Modules/Alerts/Rules.lua" 2>&1 | tail -12; echo "exit ${PIPESTATUS[0]}"
echo "== alerts engine"; node run_alerts_engine.js "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" 2>&1 | tail -12; echo "exit ${PIPESTATUS[0]}"
echo "== alerts notes"; node run_alerts_notes.js old_Engine.lua old_Alert.lua "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Notes/Engine.lua" "$WA/CRT_Modules/Notes/Window.lua" "$WA/CRT_Modules/Notes/Alert.lua" "$WA/CRT_Modules/Alerts/Speech.lua" "$WA/CRT_Core/Sound/Engine.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== alerts speech"; node run_alerts_speech.js "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Core/Sound/Engine.lua" "$WA/CRT_Modules/Alerts/Speech.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== alerts reminders"; node run_alerts_reminders.js "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Timeline/Lanes.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" "$WA/CRT_Data/Bosses/Registry.lua" "$WA/CRT_Data/Seasons/Midnight-S1/Season.lua" "$WA/CRT_Data/Seasons/Midnight-S1/NekzaliTheSoulcoiler.lua" 2>&1  | tail -12; echo "exit ${PIPESTATUS[0]}"
echo "== alerts phases"; node run_alerts_phases.js "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Alerts/PhaseDatabase.lua" "$WA/CRT_Modules/Alerts/Phases.lua" 2>&1 | tail -12; echo "exit ${PIPESTATUS[0]}"
echo "== alerts bars"; node run_alerts_bars.js "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Alerts/Areas.lua" "$WA/CRT_Modules/Alerts/Bars.lua" 2>&1 | tail -14; echo "exit ${PIPESTATUS[0]}"
echo "== alerts areas"; node run_alerts_areas.js "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Alerts/Areas.lua" "$WA/CRT_Modules/Alerts/Texts.lua" 2>&1 | tail -14; echo "exit ${PIPESTATUS[0]}"
echo "== alerts icons"; node run_alerts_icons.js "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Alerts/Areas.lua" "$WA/CRT_Modules/Alerts/Icons.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== alerts circles"; node run_alerts_circles.js "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Alerts/Areas.lua" "$WA/CRT_Modules/Alerts/Circles.lua" "$WA/CRT_Core/UI/Controls.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== alerts editor"; node run_alerts_editor.js "$WA/CRT_Core/UI/Panel.lua" "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Timeline/Lanes.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Core/Sound/Engine.lua" "$WA/CRT_Modules/Alerts/Speech.lua" "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Notes/Engine.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" "$WA/CRT_Modules/Alerts/Draft.lua" "$WA/CRT_Modules/Alerts/SpellLookup.lua" "$WA/CRT_Modules/Alerts/Editor.lua" "$WA/CRT_Core/UI/Controls.lua" 2>&1 | tail -22; echo "exit ${PIPESTATUS[0]}"
echo "== alerts saved"; node run_alerts_saved.js "$WA/CRT_Core/UI/Panel.lua" "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Timeline/Lanes.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Core/Sound/Engine.lua" "$WA/CRT_Modules/Alerts/Speech.lua" "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Notes/Engine.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" "$WA/CRT_Modules/Alerts/Draft.lua" "$WA/CRT_Modules/Alerts/SpellLookup.lua" "$WA/CRT_Modules/Alerts/Editor.lua" "$WA/CRT_Modules/Alerts/Saved.lua" "$WA/CRT_Modules/Timeline/View.lua" 2>&1 | tail -12; echo "exit ${PIPESTATUS[0]}"
echo "== alerts tabs"; node run_alerts_tabs.js "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Timeline/Lanes.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" "$WA/CRT_Modules/Alerts/PhaseDatabase.lua" "$WA/CRT_Modules/Alerts/Phases.lua" "$WA/CRT_Core/Sound/Engine.lua" "$WA/CRT_Modules/Alerts/Draft.lua" "$WA/CRT_Modules/Alerts/SpellLookup.lua" "$WA/CRT_Modules/Notes/Reminders.lua" "$WA/CRT_Modules/Notes/Phases.lua" "$WA/CRT_Modules/Notes/Page.lua" 2>&1 | tail -20; echo "exit ${PIPESTATUS[0]}"
echo "== mechalerts"; node run_mechalerts.js "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Timeline/Lanes.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Core/Sound/Engine.lua" "$WA/CRT_Core/Sound/Auras.lua" "$WA/CRT_Modules/Alerts/Speech.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" "$WA/CRT_Modules/Alerts/Draft.lua" "$WA/CRT_Modules/Alerts/SpellLookup.lua" "$WA/CRT_Modules/Alerts/Editor.lua" "$WA/CRT_Modules/Notes/Reminders.lua" "$WA/CRT_Core/UI/Controls.lua" 2>&1 | tail -20; echo "exit ${PIPESTATUS[0]}"
echo "== alerts timeline"; node run_alerts_timeline.js "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Timeline/Lanes.lua" "$WA/CRT_Modules/Timeline/View.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" "$WA/CRT_Core/Slash.lua" 2>&1 | tail -14; echo "exit ${PIPESTATUS[0]}"
echo "== alerts fields"; node run_alerts_fields.js "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Timeline/Lanes.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" "$WA/CRT_Core/Sound/Engine.lua" "$WA/CRT_Modules/Alerts/Speech.lua" 2>&1 | tail -14; echo "exit ${PIPESTATUS[0]}"
echo "== alerts notefields"; node run_alerts_notefields.js "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Alerts/Speech.lua" "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Notes/Engine.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== alerts notewrite"; node run_alerts_notewrite.js "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== alerts marks"; node run_alerts_marks.js "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Timeline/Lanes.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" "$WA/CRT_Modules/Timeline/View.lua" "$WA/CRT_Data/Bosses/Registry.lua" "$WA/CRT_Data/Seasons/Midnight-S1/Season.lua" "$WA/CRT_Data/Seasons/Midnight-S1/NekzaliTheSoulcoiler.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== alerts layout"; node run_alerts_layout.js "$WA/CRT_Modules/Alerts/Areas.lua" "$WA/CRT_Modules/Alerts/Icons.lua" "$WA/CRT_Modules/Alerts/Texts.lua" "$WA/CRT_Modules/Alerts/Bars.lua" "$WA/CRT_Modules/Alerts/Circles.lua" "$WA/CRT_Modules/Notes/Alert.lua" 2>&1 | tail -6; echo "exit ${PIPESTATUS[0]}"
echo "== alerts alertstab"; node run_alerts_alertstab.js "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Notes/Settings.lua" "$WA/CRT_Modules/Notes/AlertsTab.lua" "$WA/CRT_Modules/Notes/Page.lua" "$WA/CRT_Modules/Alerts/Areas.lua" "$WA/CRT_Modules/Alerts/Bars.lua" "$WA/CRT_Modules/Alerts/Texts.lua" "$WA/CRT_Modules/Alerts/Icons.lua" "$WA/CRT_Modules/Alerts/Circles.lua" "$WA/CRT_Core/UI/Controls.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== notesettings"; node run_notesettings.js "$WA/CRT_Modules/Notes/Settings.lua" "$WA/CRT_Modules/Notes/Page.lua" 2>&1 | tail -4; echo "exit ${PIPESTATUS[0]}"
echo "== notestabs"; node run_notestabs.js "$WA/CRT_Modules/Notes/Settings.lua" "$WA/CRT_Modules/Notes/Page.lua" 2>&1 | tail -4; echo "exit ${PIPESTATUS[0]}"
echo "== alerts strip"; node run_alerts_strip.js "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Timeline/Lanes.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" "$WA/CRT_Modules/Alerts/Saved.lua" "$WA/CRT_Modules/Timeline/View.lua" "$WA/CRT_Data/Bosses/Registry.lua" "$WA/CRT_Data/Seasons/Midnight-S1/Season.lua" "$WA/CRT_Data/Seasons/Midnight-S1/NekzaliTheSoulcoiler.lua" "$WA/CRT_Core/UI/Panel.lua" "$WA/CRT_Modules/Alerts/Cooldowns.lua" "$WA/CRT_Core/UI/Controls.lua" "$WA/CRT_Modules/Alerts/CooldownData.lua" "$WA/CRT_Modules/Groups/Data.lua" "$WA/CRT_Modules/Alerts/Draft.lua" "$WA/CRT_Modules/Alerts/Roster.lua" "$WA/CRT_Core/Sound/Engine.lua" 2>&1 | tail -30; echo "exit ${PIPESTATUS[0]}"
echo "== alerts cooldowns"; node run_alerts_cooldowns.js "$WA/CRT_Modules/Alerts/CooldownData.lua" "$WA/CRT_Modules/Alerts/Cooldowns.lua" 2>&1 | tail -6; echo "exit ${PIPESTATUS[0]}"
echo "== controls"; node run_controls.js "$WA" 2>&1 | tail -40; echo "exit ${PIPESTATUS[0]}"
echo "== notes share"; node run_notes_share.js "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Notes/Comm.lua" "$WA/CRT_Modules/Notes/Settings.lua" "$WA/CRT_Modules/Notes/Page.lua" 2>&1 | tail -8; echo "exit ${PIPESTATUS[0]}"
echo "== alerts personalwin"; node run_alerts_personalwin.js "$WA/CRT_Data/Bosses/Registry.lua" "$WA/CRT_Data/Seasons/Midnight-S1/Season.lua" "$WA/CRT_Data/Seasons/Midnight-S1/NekzaliTheSoulcoiler.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Notes/Engine.lua" "$WA/CRT_Modules/Notes/Window.lua" "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== alerts rehearsal"; node run_alerts_rehearsal.js "$WA/CRT_Data/Bosses/Registry.lua" "$WA/CRT_Data/Seasons/Midnight-S1/Season.lua" "$WA/CRT_Data/Seasons/Midnight-S1/NekzaliTheSoulcoiler.lua" "$WA/CRT_Modules/Groups/Data.lua" "$WA/CRT_Modules/Alerts/Rules.lua" "$WA/CRT_Modules/Alerts/Engine.lua" "$WA/CRT_Core/Sound/Engine.lua" "$WA/CRT_Modules/Alerts/Speech.lua" "$WA/CRT_Modules/Notes/Parse.lua" "$WA/CRT_Modules/Notes/Data.lua" "$WA/CRT_Modules/Notes/Engine.lua" "$WA/CRT_Modules/Notes/Window.lua" "$WA/CRT_Modules/Timeline/Data.lua" "$WA/CRT_Modules/Timeline/Database.lua" "$WA/CRT_Modules/Timeline/Reference.lua" "$WA/CRT_Modules/Alerts/Roster.lua" "$WA/CRT_Modules/Alerts/Reminders.lua" "$WA/CRT_Modules/Alerts/Areas.lua" "$WA/CRT_Modules/Alerts/Bars.lua" "$WA/CRT_Modules/Alerts/Icons.lua" 2>&1 | tail -20; echo "exit ${PIPESTATUS[0]}"
echo "== reference types"; node run_reftypes.js "$W" 2>&1 | tail -2
echo "== drag starts from the mouse"; bad=$(grep -rn "StartMoving" --include=*.lua --exclude-dir=.claude --exclude-dir=Tests --exclude-dir=node_modules "$W" | grep -v "WindowLog.lua" | grep -v "StartMoving(true)"); if [ -n "$bad" ]; then echo "FAIL StartMoving without true:"; echo "$bad"; else echo "all passed"; fi
echo "== two looks, no third"; bad=$(grep -rnE 'IsFlat|ui\.style|"minimal"|Minimal black' --include=*.lua --exclude-dir=.claude --exclude-dir=Tests --exclude-dir=node_modules "$W"); if [ -n "$bad" ]; then echo "FAIL code still reads the removed third look:"; echo "$bad"; else echo "all passed"; fi
echo "== fit text"; node run_fittext.js "$W" 2>&1 | tail -1
echo "== loot rclc"; node run_loot_rclc.js "$W" 2>&1 | tail -6; echo "exit ${PIPESTATUS[0]}"
echo "== lootmaster data"; node run_lootmaster_data.js "$W" 2>&1 | tail -6; echo "exit ${PIPESTATUS[0]}"
echo "== lootmaster comm"; node run_lootmaster_comm.js "$W" 2>&1 | tail -6; echo "exit ${PIPESTATUS[0]}"
echo "== lootmaster sync"; node run_lootmaster_sync.js "$W" 2>&1 | tail -6; echo "exit ${PIPESTATUS[0]}"
echo "== lootmaster autopass"; node run_lootmaster_autopass.js "$W" 2>&1 | tail -6; echo "exit ${PIPESTATUS[0]}"
echo "== lootmaster looting"; node run_lootmaster_looting.js "$W" 2>&1 | tail -6; echo "exit ${PIPESTATUS[0]}"
echo "== RollOnLoot only in the auto-pass gate"; bad=$(grep -rln "RollOnLoot" --include=*.lua --exclude-dir=.claude --exclude-dir=Tests --exclude-dir=node_modules "$W" | sed 's#\\#/#g' | grep -v "/LootMaster/AutoPass\.lua$" | grep -v "/Dev/LootProbe\.lua$"); if [ -n "$bad" ]; then echo "FAIL RollOnLoot outside CRT_Modules/LootMaster/AutoPass.lua (CRT_Dev/Dev/LootProbe.lua is exempt):"; echo "$bad"; else echo "all passed"; fi
echo "== lootmaster score"; node run_lootmaster_score.js "$W" 2>&1 | tail -6; echo "exit ${PIPESTATUS[0]}"
echo "== lootmaster ui"; node run_lootmaster_ui.js "$W" 2>&1 | tail -6; echo "exit ${PIPESTATUS[0]}"
echo "== lootmaster filter"; node run_lootmaster_filter.js "$W" 2>&1 | tail -6; echo "exit ${PIPESTATUS[0]}"
echo "== debuffs"; node run_debuffs.js "$W" 2>&1 | tail -12; echo "exit ${PIPESTATUS[0]}"
echo "== late data"; node run_late.js "$W/CRT_Modules/Late/Data.lua" 2>&1 | tail -6; echo "exit ${PIPESTATUS[0]}"
echo "== late page"; node run_latepage.js "$W/CRT_Modules/Late/Data.lua" "$W/CRT_Modules/Late/Page.lua" 2>&1 | tail -2; echo "exit ${PIPESTATUS[0]}"
echo "== groups extras"; node run_groups_extras.js "$W" 2>&1 | tail -2; echo "exit ${PIPESTATUS[0]}"
echo "== Lua 5.1 upvalue limit (60 per function; the harnesses run a newer Lua that allows 255)"; node lua-upvalue-check.cjs "$W" | grep -v "^OK"; up=${PIPESTATUS[0]}; if [ "$up" = "0" ]; then echo "all passed"; else echo "FAIL a function has more than 60 upvalues"; fi
echo "== boss route"; node run_bossroute.js "$W" 2>&1 | tail -1
echo "== journal export"; node run_journal_export.js "$W" 2>&1 | tail -2; echo "exit ${PIPESTATUS[0]}"
echo "== journal walk"; node run_journal_walk.js "$W" 2>&1 | tail -2; echo "exit ${PIPESTATUS[0]}"
echo "== timeline undo"; node run_timeline_undo.js "$W" 2>&1 | tail -3; echo "exit ${PIPESTATUS[0]}"
echo "== notes order"; node run_notesorder.js "$W" 2>&1 | tail -1
