echo "== timeline rehearsal window"; node run_timeline_rehearsalwin.js "$W/CRT_Modules/Timeline/Rehearsal.lua" "$W/CRT_Modules/Timeline/RehearsalWindow.lua" 2>&1 | tail -15; echo "exit ${PIPESTATUS[0]}"
